using System.Reflection;
using System.Reflection.Metadata;
using System.Reflection.PortableExecutable;

namespace PaymentAuthorization.ArchitectureTest;

public sealed class LayerRulesTests
{
    // Technical (I/O, network, persistence) namespaces the business layers must never touch.
    private static readonly string[] TechnicalNamespaces =
    [
        "System.IO", "System.Net", "System.Data", "System.Diagnostics.Process",
        "System.Security.Cryptography", "Microsoft.Data", "Microsoft.EntityFrameworkCore",
        "Microsoft.Extensions.Http",
    ];

    [Fact]
    public void Domain_depends_on_no_other_layer_and_no_technical_detail() =>
        AssertClean("PaymentAuthorization.Domain",
            forbiddenAssemblies: ["PaymentAuthorization.Application", "PaymentAuthorization.Infrastructure"]);

    [Fact]
    public void Application_depends_only_on_the_domain_and_no_technical_detail() =>
        AssertClean("PaymentAuthorization.Application",
            forbiddenAssemblies: ["PaymentAuthorization.Infrastructure"]);

    private static void AssertClean(string assemblyName, string[] forbiddenAssemblies)
    {
        var path = Assembly.Load(assemblyName).Location;
        using var stream = File.OpenRead(path);
        using var pe = new PEReader(stream);
        var md = pe.GetMetadataReader();

        var violations = new List<string>();
        foreach (var handle in md.AssemblyReferences)
        {
            var name = md.GetString(md.GetAssemblyReference(handle).Name);
            if (forbiddenAssemblies.Contains(name)) violations.Add($"assembly {name}");
        }
        foreach (var handle in md.TypeReferences)
        {
            var type = md.GetTypeReference(handle);
            var ns = md.GetString(type.Namespace);
            if (TechnicalNamespaces.Any(t => ns == t || ns.StartsWith(t + ".")))
                violations.Add($"{ns}.{md.GetString(type.Name)}");
        }

        Assert.True(violations.Count == 0, $"{assemblyName} has layer violations: {string.Join(", ", violations)}");
    }
}
